    if (!(W > 0.5 && Hh > 0.5)) return;
    var cx = (safe.x + m)*scale + safe.w*scale*b.x, cy = (safe.y + m)*scale + safe.h*scale*b.y;
    var tinted = tintMask(im, W, Hh, tintHex(d.tint)); if (!tinted) return;
