        x.save(); x.fillStyle = "rgba(0,0,0,.45)"; x.beginPath(); x.ellipse(cx, cy + pageH*0.52, pageW*1.9, pageH*0.12, 0, 0, Math.PI*2); x.fill(); x.restore();
