    if (dir > 0){ next = (pair[1] != null) ? pair[1] + 1 : (pair[0] != null ? pair[0] + 1 : at + 1); if (next >= n) return false; }
    else { next = (pair[0] != null) ? pair[0] - 1 : -1; if (pair[0] === 0) next = -1; if (next < 0) return false; }
